public String[] AndroidThunkJava_OpenMobileDeviceGetPreferredLanguages()
{
	android.content.res.Configuration configuration = getResources().getConfiguration();
	if (android.os.Build.VERSION.SDK_INT >= 24)
	{
		android.os.LocaleList locales = configuration.getLocales();
		String[] languages = new String[locales.size()];
		for (int index = 0; index < locales.size(); ++index)
		{
			languages[index] = locales.get(index).toLanguageTag();
		}
		return languages;
	}
	return configuration.locale == null
		? new String[0]
		: new String[] { configuration.locale.toLanguageTag() };
}

public String[] AndroidThunkJava_OpenMobileDeviceGetLocaleDetails()
{
	android.content.res.Configuration configuration = getResources().getConfiguration();
	java.util.Locale locale = android.os.Build.VERSION.SDK_INT >= 24
		? configuration.getLocales().get(0)
		: configuration.locale;
	if (locale == null)
	{
		return new String[0];
	}
	String currencyCode = "";
	try
	{
		java.util.Currency currency = java.util.Currency.getInstance(locale);
		currencyCode = currency == null ? "" : currency.getCurrencyCode();
	}
	catch (IllegalArgumentException ignored)
	{
	}
	return new String[] {
		locale.toLanguageTag(),
		locale.getLanguage(),
		locale.getScript(),
		locale.getCountry(),
		currencyCode
	};
}

public String[] AndroidThunkJava_OpenMobileDeviceGetTimeZoneAt(long utcMilliseconds)
{
	java.util.TimeZone timeZone = java.util.TimeZone.getDefault();
	String identifier = timeZone.getID();
	if (android.os.Build.VERSION.SDK_INT >= 24)
	{
		String canonicalIdentifier = android.icu.util.TimeZone.getCanonicalID(identifier);
		if (canonicalIdentifier != null && !canonicalIdentifier.isEmpty())
		{
			identifier = canonicalIdentifier;
		}
	}
	java.util.Date instant = new java.util.Date(utcMilliseconds);
	return new String[] {
		identifier,
		Integer.toString(timeZone.getOffset(utcMilliseconds) / 1000),
		Boolean.toString(timeZone.inDaylightTime(instant))
	};
}

public String[] AndroidThunkJava_OpenMobileDeviceGetRegionalPreferences()
{
	String timeFormat = android.text.format.DateFormat.is24HourFormat(this)
		? "24"
		: "12";
	String measurementSystem = "";
	if (android.os.Build.VERSION.SDK_INT >= 28)
	{
		android.content.res.Configuration configuration = getResources().getConfiguration();
		java.util.Locale locale = configuration.getLocales().get(0);
		if (locale != null && !locale.getCountry().isEmpty())
		{
			android.icu.util.LocaleData.MeasurementSystem nativeSystem =
				android.icu.util.LocaleData.getMeasurementSystem(
					android.icu.util.ULocale.forLocale(locale)
				);
			if (nativeSystem == android.icu.util.LocaleData.MeasurementSystem.SI)
			{
				measurementSystem = "metric";
			}
			else if (nativeSystem == android.icu.util.LocaleData.MeasurementSystem.US)
			{
				measurementSystem = "imperial";
			}
		}
	}
	return new String[] { timeFormat, measurementSystem };
}

private android.content.BroadcastReceiver OpenMobileDeviceLocaleReceiver;

public native void nativeOpenMobileDeviceLocaleChanged();

public boolean AndroidThunkJava_OpenMobileDeviceStartLocaleMonitoring()
{
	if (OpenMobileDeviceLocaleReceiver != null)
	{
		return true;
	}
	android.content.IntentFilter filter = new android.content.IntentFilter();
	filter.addAction(android.content.Intent.ACTION_LOCALE_CHANGED);
	filter.addAction(android.content.Intent.ACTION_CONFIGURATION_CHANGED);
	filter.addAction(android.content.Intent.ACTION_TIME_CHANGED);
	filter.addAction(android.content.Intent.ACTION_TIMEZONE_CHANGED);
	filter.addAction(android.content.Intent.ACTION_DATE_CHANGED);
	if (android.os.Build.VERSION.SDK_INT >= 33)
	{
		filter.addAction(android.content.Intent.ACTION_APPLICATION_LOCALE_CHANGED);
	}
	OpenMobileDeviceLocaleReceiver = new android.content.BroadcastReceiver()
	{
		@Override
		public void onReceive(
			android.content.Context context,
			android.content.Intent intent
		)
		{
			nativeOpenMobileDeviceLocaleChanged();
		}
	};
	try
	{
		if (android.os.Build.VERSION.SDK_INT >= 33)
		{
			registerReceiver(
				OpenMobileDeviceLocaleReceiver,
				filter,
				android.content.Context.RECEIVER_NOT_EXPORTED
			);
		}
		else
		{
			registerReceiver(OpenMobileDeviceLocaleReceiver, filter);
		}
		return true;
	}
	catch (RuntimeException ignored)
	{
		OpenMobileDeviceLocaleReceiver = null;
		return false;
	}
}

public void AndroidThunkJava_OpenMobileDeviceStopLocaleMonitoring()
{
	if (OpenMobileDeviceLocaleReceiver == null)
	{
		return;
	}
	try
	{
		unregisterReceiver(OpenMobileDeviceLocaleReceiver);
	}
	catch (IllegalArgumentException ignored)
	{
	}
	OpenMobileDeviceLocaleReceiver = null;
}

public String[] AndroidThunkJava_OpenMobileDeviceGetBatteryDetails()
{
	android.content.IntentFilter filter = new android.content.IntentFilter(
		android.content.Intent.ACTION_BATTERY_CHANGED
	);
	android.content.Intent battery = android.os.Build.VERSION.SDK_INT >= 33
		? registerReceiver(
			null,
			filter,
			android.content.Context.RECEIVER_NOT_EXPORTED
		)
		: registerReceiver(null, filter);
	if (battery == null)
	{
		return new String[0];
	}
	android.os.PowerManager powerManager = (android.os.PowerManager)
		getSystemService(android.content.Context.POWER_SERVICE);
	return new String[] {
		Integer.toString(battery.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL, -1)),
		Integer.toString(battery.getIntExtra(android.os.BatteryManager.EXTRA_SCALE, -1)),
		Boolean.toString(battery.getBooleanExtra(android.os.BatteryManager.EXTRA_PRESENT, true)),
		battery.hasExtra(android.os.BatteryManager.EXTRA_STATUS)
			? Integer.toString(battery.getIntExtra(android.os.BatteryManager.EXTRA_STATUS, 0))
			: "",
		battery.hasExtra(android.os.BatteryManager.EXTRA_PLUGGED)
			? Integer.toString(battery.getIntExtra(android.os.BatteryManager.EXTRA_PLUGGED, 0))
			: "",
		powerManager == null ? "" : Boolean.toString(powerManager.isPowerSaveMode()),
		powerManager != null && android.os.Build.VERSION.SDK_INT >= 29
			? Integer.toString(powerManager.getCurrentThermalStatus())
			: ""
	};
}

