public String[] AndroidThunkJava_OpenMobileDeviceGetStorageSpace()
{
	try
	{
		java.io.File dataDirectory = getFilesDir();
		if (dataDirectory == null)
		{
			return new String[0];
		}
		android.os.StatFs stats = new android.os.StatFs(
			dataDirectory.getAbsolutePath()
		);
		return new String[]
		{
			Long.toString(stats.getTotalBytes()),
			Long.toString(stats.getAvailableBytes())
		};
	}
	catch (RuntimeException ignored)
	{
		return new String[0];
	}
}

public String[] AndroidThunkJava_OpenMobileDeviceGetNetworkPath()
{
	try
	{
		android.net.ConnectivityManager manager =
			(android.net.ConnectivityManager) getSystemService(
				android.content.Context.CONNECTIVITY_SERVICE
			);
		if (manager == null)
		{
			return new String[0];
		}
		if (android.os.Build.VERSION.SDK_INT < 23)
		{
			android.net.NetworkInfo info = manager.getActiveNetworkInfo();
			boolean active = info != null && info.isConnected();
			return new String[] {
				Boolean.toString(active),
				"false", "false", "false",
				"false", "false", "false", "false", "",
				"false", "false", "false", "false"
			};
		}
		android.net.Network network = manager.getActiveNetwork();
		if (network == null)
		{
			return new String[] {
				"false", "false", "false", "false",
				Boolean.toString(android.os.Build.VERSION.SDK_INT >= 23),
				"false", "false", "false", "",
				"false", "false", "false", "false"
			};
		}
		android.net.NetworkCapabilities capabilities =
			manager.getNetworkCapabilities(network);
		if (capabilities == null)
		{
			return new String[] {
				"true", "false", "false", "false",
				Boolean.toString(android.os.Build.VERSION.SDK_INT >= 23),
				"false", "false", "false", "",
				"false", "false", "false", "false"
			};
		}
		boolean captiveSupported = android.os.Build.VERSION.SDK_INT >= 23;
		boolean local = android.os.Build.VERSION.SDK_INT >= 35
			&& capabilities.hasCapability(
				android.net.NetworkCapabilities.NET_CAPABILITY_LOCAL_NETWORK
			);
		boolean temporarilyNotMetered =
			android.os.Build.VERSION.SDK_INT >= 30
			&& capabilities.hasCapability(
				android.net.NetworkCapabilities.NET_CAPABILITY_TEMPORARILY_NOT_METERED
			);
		boolean metered = !capabilities.hasCapability(
			android.net.NetworkCapabilities.NET_CAPABILITY_NOT_METERED
		) && !temporarilyNotMetered;
		boolean constrainedAvailable = android.os.Build.VERSION.SDK_INT >= 36;
		final int notBandwidthConstrainedCapability = 37;
		boolean constrained = constrainedAvailable
			&& !capabilities.hasCapability(
				notBandwidthConstrainedCapability
			);
		return new String[] {
			"true",
			"true",
			Boolean.toString(capabilities.hasCapability(
				android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET
			)),
			Boolean.toString(capabilities.hasCapability(
				android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED
			)),
			Boolean.toString(captiveSupported),
			Boolean.toString(captiveSupported
				&& capabilities.hasCapability(
					android.net.NetworkCapabilities.NET_CAPABILITY_CAPTIVE_PORTAL
				)),
			Boolean.toString(local),
			Boolean.toString(!capabilities.hasCapability(
				android.net.NetworkCapabilities.NET_CAPABILITY_NOT_RESTRICTED
			)),
			AndroidThunkJava_OpenMobileDeviceGetTransportTypes(capabilities),
			"true",
			Boolean.toString(metered),
			Boolean.toString(constrainedAvailable),
			Boolean.toString(constrained)
		};
	}
	catch (RuntimeException ignored)
	{
		return new String[0];
	}
}

private String AndroidThunkJava_OpenMobileDeviceGetTransportTypes(
	android.net.NetworkCapabilities capabilities
)
{
	int[] baseTypes = {
		android.net.NetworkCapabilities.TRANSPORT_CELLULAR,
		android.net.NetworkCapabilities.TRANSPORT_WIFI,
		android.net.NetworkCapabilities.TRANSPORT_BLUETOOTH,
		android.net.NetworkCapabilities.TRANSPORT_ETHERNET,
		android.net.NetworkCapabilities.TRANSPORT_VPN
	};
	java.util.ArrayList<Integer> transportTypes =
		new java.util.ArrayList<Integer>();
	for (int type : baseTypes)
	{
		if (capabilities.hasTransport(type))
		{
			transportTypes.add(type);
		}
	}
	if (android.os.Build.VERSION.SDK_INT >= 26
		&& capabilities.hasTransport(
			android.net.NetworkCapabilities.TRANSPORT_WIFI_AWARE
		))
	{
		transportTypes.add(
			android.net.NetworkCapabilities.TRANSPORT_WIFI_AWARE
		);
	}
	if (android.os.Build.VERSION.SDK_INT >= 27
		&& capabilities.hasTransport(
			android.net.NetworkCapabilities.TRANSPORT_LOWPAN
		))
	{
		transportTypes.add(
			android.net.NetworkCapabilities.TRANSPORT_LOWPAN
		);
	}
	if (android.os.Build.VERSION.SDK_INT >= 31
		&& capabilities.hasTransport(
			android.net.NetworkCapabilities.TRANSPORT_USB
		))
	{
		transportTypes.add(
			android.net.NetworkCapabilities.TRANSPORT_USB
		);
	}
	if (android.os.Build.VERSION.SDK_INT >= 34
		&& capabilities.hasTransport(
			android.net.NetworkCapabilities.TRANSPORT_THREAD
		))
	{
		transportTypes.add(
			android.net.NetworkCapabilities.TRANSPORT_THREAD
		);
	}
	if (android.os.Build.VERSION.SDK_INT >= 35
		&& capabilities.hasTransport(
			android.net.NetworkCapabilities.TRANSPORT_SATELLITE
		))
	{
		transportTypes.add(
			android.net.NetworkCapabilities.TRANSPORT_SATELLITE
		);
	}
	StringBuilder result = new StringBuilder();
	for (int type : transportTypes)
	{
		if (result.length() > 0)
		{
			result.append(',');
		}
		result.append(type);
	}
	return result.toString();
}

public boolean AndroidThunkJava_OpenMobileDeviceStartNetworkMonitoring()
{
	if (OpenMobileDeviceNetworkCallback != null)
	{
		return true;
	}
	if (android.os.Build.VERSION.SDK_INT < 24)
	{
		return false;
	}
	android.net.ConnectivityManager manager =
		(android.net.ConnectivityManager) getSystemService(
			android.content.Context.CONNECTIVITY_SERVICE
		);
	if (manager == null)
	{
		return false;
	}
	android.net.ConnectivityManager.NetworkCallback callback =
		new android.net.ConnectivityManager.NetworkCallback()
		{
			@Override
			public void onAvailable(android.net.Network network)
			{
				nativeOpenMobileDeviceNetworkChanged();
			}

			@Override
			public void onLost(android.net.Network network)
			{
				nativeOpenMobileDeviceNetworkChanged();
			}

			@Override
			public void onCapabilitiesChanged(
				android.net.Network network,
				android.net.NetworkCapabilities capabilities
			)
			{
				nativeOpenMobileDeviceNetworkChanged();
			}

			@Override
			public void onBlockedStatusChanged(
				android.net.Network network,
				boolean blocked
			)
			{
				nativeOpenMobileDeviceNetworkChanged();
			}
		};
	try
	{
		manager.registerDefaultNetworkCallback(callback);
		OpenMobileDeviceNetworkCallback = callback;
		return true;
	}
	catch (RuntimeException ignored)
	{
		return false;
	}
}

public void AndroidThunkJava_OpenMobileDeviceStopNetworkMonitoring()
{
	if (OpenMobileDeviceNetworkCallback == null)
	{
		return;
	}
	android.net.ConnectivityManager manager =
		(android.net.ConnectivityManager) getSystemService(
			android.content.Context.CONNECTIVITY_SERVICE
		);
	if (manager != null)
	{
		try
		{
			manager.unregisterNetworkCallback(
				OpenMobileDeviceNetworkCallback
			);
		}
		catch (RuntimeException ignored)
		{
		}
	}
	OpenMobileDeviceNetworkCallback = null;
}

public boolean AndroidThunkJava_OpenMobileDeviceStartMemoryMonitoring()
{
	if (OpenMobileDeviceMemoryCallbacks != null)
	{
		return true;
	}
	android.content.ComponentCallbacks2 callbacks =
		new android.content.ComponentCallbacks2()
		{
			@Override
